changeSet.sql:
CREATE TABLE countries ( id SERIAL PRIMARY KEY, name VARCHAR(32), num_code INTEGER, char_code VARCHAR(32) );
CREATE TABLE rate_dict ( id SERIAL PRIMARY KEY, name VARCHAR(32), num_code INTEGER, char_code VARCHAR(32) );
CREATE TABLE rates ( id SERIAL PRIMARY KEY, created TIMESTAMP WITHOUT TIME ZONE, updated TIMESTAMP WITHOUT TIME ZONE, currency_id VARCHAR(32), country_id INTEGER NOT NULL, rate_dict_id INTEGER NOT NULL, rate_date TIMESTAMP WITHOUT TIME ZONE, nominal BIGINT, value DECIMAL, FOREIGN KEY (country_id) REFERENCES countries(id), FOREIGN KEY (rate_dict_id) REFERENCES rate_dict(id) );
